hooks.command:
set -- $(head -c 65537 | awk '
# Flattens JSON text into V[path] = raw scalar (".tool_input.path", "#.status").
# Escapes are neutralized first: an escaped backslash is \001 and an escaped
# quote \002, so outer strings are "[^"]*"; in a JSON text held in a string,
# \001 escapes the next character.
function flat(s, pre, inner,   n, tk, i, x, d, p, P, K, I, W, key) {
  gsub(inner ? q "([^" q "\001]|\001.)*" q "|[][{}:,]" : q "[^" q "]*" q "|[][{}:,]", "\n&\n", s)
  n = split(s, tk, "\n"); d = 0
  for (i = 1; i <= n; i++) {
    x = tk[i]; sub(/^[ \t\r]+/, "", x); sub(/[ \t\r]+$/, "", x)
    if (x == "") continue
    if (x == ":") { W[d] = 0; continue }
    if (x == ",") { if (K[d] == "[") I[d]++; else W[d] = 1; continue }
    if (x == "}" || x == "]") { if (d > 0) d--; continue }
    if (d > 0 && K[d] == "{" && W[d]) { key[d] = substr(x, 2, length(x) - 2); continue }
    if (d == 0) p = pre
    else if (K[d] == "{") p = P[d] "." key[d]
    else p = P[d] "[" I[d] "]"
    if (x == "{" || x == "[") { d++; K[d] = x; P[d] = p; I[d] = 0; W[d] = (x == "{"); continue }
    if (!(p in V)) V[p] = x
  }
}
function str(x) { return substr(x, 1, 1) == q ? substr(x, 2, length(x) - 2) : "" }
BEGIN { q = sprintf("%c", 34) }
{ t = t $0 " " }
END {
  if (length(t) > 65536) exit
  gsub(/\\\\/, "\001", t); gsub(/\\"/, "\002", t)
  flat(t, "", 0)
  p = str(V[".tool_input.path"]); sub(/\/$/, "", p)
  if (V[".tool_input.method"] != q "POST" q) exit
  if (p == "/deploy" || p ~ /^\/deploy\/[^\/]+\/convex\/deploy$/) m = "app"
  else if (p == "/payments/payment-links") m = "payment-link"
  else if (p ~ /^\/ads\/[^\/]+\/campaigns\/[^\/]+\/launch$/ || p ~ /^\/ads\/linkedin\/campaign-groups\/[^\/]+\/launch$/) m = "ads"
  else if (p ~ /^\/outreach\/instantly\/campaigns\/[^\/]+\/activate$/) m = "email"
  else exit
  # The HTTP status of egbe_write: a structured result, or the JSON text of its MCP content.
  s = V[".tool_response.status"]
  if (s == "") s = V[".tool_response.structuredContent.status"]
  if (s == "") {
    x = str(V[".tool_response[0].text"])
    if (x == "") x = str(V[".tool_response.content[0].text"])
    if (x == "") x = str(V[".tool_response"])
    gsub("\002", q, x); gsub(/\\./, " ", x)
    flat(x, "#", 1); s = V["#.status"]
  }
  if (s !~ /^2[0-9][0-9]$/) exit
  x = str(V[".session_id"])
  if (x !~ /^[A-Za-z0-9_-]+$/) x = "-"
  print x, m
}' 2>/dev/null)
case $2 in
  app) w='started publishing an app' ;;
  payment-link) w='created a payment link' ;;
  ads) w='launched an ad campaign' ;;
  email) w='activated an email campaign' ;;
  *) exit 0 ;;
esac
d=${CLAUDE_PLUGIN_DATA:-$HOME/.claude/plugins/data/egbe}/loop-offer
if [ "$1" != - ] && mkdir -p "$d" 2>/dev/null; then
  [ -e "$d/$1.$2" ] && exit 0
  : >"$d/$1.$2" 2>/dev/null
  find "$d" -type f -mtime +1 -exec rm -f {} + 2>/dev/null
fi
printf '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"%s"}}\n' "Egbe milestone: this call $w. When this work is done and verified, check once whether a Business Loop fits it, such as a recurring report, product-health check or campaign oversight. If one fits, offer it as your reply's next step as the Offer a Business Loop section of egbe-os-product-routines references/run-preset.md describes, and save or start it only after the founder agrees. Skip this if a loop already covers it, the founder declined one or asked for no suggestions."
exit 0
